import { Suspense, lazy } from 'preact/compat';
import { useEffect, useState } from 'preact/hooks';
import { FunctionalComponent } from 'preact';
import cn from 'classnames';

import { trackAmplitudeEvent } from '../../../../../shared/analytics';
import styles from './styles.module.scss';
import { SearchResponse } from '../../slice/types';

const ImagePopup = lazy(() => import('./ImagePopup'));

interface Props {
  data: SearchResponse,
  $form: HTMLFormElement,
}

const ROW_HEIGHT = 92;
const COLUMNS = 2;
const DESIRED_COLUMN_WIDTH = 200;
const MIN_WIDTH = 200;
const MAX_WIDTH = 600;

const InstantAnswer: FunctionalComponent<Props> = ({ data, $form }: Props) => {
  const [image, setImage] = useState(null);
  const [state, setState] = useState({ limit: 0, width: 0, columns: 2 });

  const handleClose = () => setImage(null);

  useEffect(() => {
    const width = Math.min((window.innerWidth - $form.offsetWidth) / 2, MAX_WIDTH);

    setState({
      columns: Math.ceil(width / DESIRED_COLUMN_WIDTH),
      width,
      limit: Math.floor((window.innerHeight - 300) / ROW_HEIGHT) * COLUMNS,
    });
  }, []);

  if (!data.images || state.width < MIN_WIDTH) return null;

  const handleSelectImage = (image) => {
    setImage(image);
    trackAmplitudeEvent(`User enlarged image`, {
      category: 'Search',
    });
  }

  return (
    <>
      {image && (
        <Suspense fallback={null}>
          <ImagePopup image={image} onClose={handleClose} />
        </Suspense>
      )}

      <div
        className={cn(styles.container)}
        style={{ width: state.width, right: -state.width }}
      >
        <h3 className={styles.title}>Images from the web</h3>

        <div className={styles.gridContainer} style={{ gridTemplateColumns: `repeat(${state.columns}, 1fr)` }}>
          {data.images.value.slice(0, state.limit).map((image) => (
            <a
              // href={image.hostPageUrl}
              onClick={() => handleSelectImage(image)}
              key={image.thumbnailUrl}
              className={styles.image}
              style={{ backgroundImage: `url(${image.thumbnailUrl})` }}
            />
          ))}
        </div>
      </div>
    </>
  )
};

export default InstantAnswer;
